const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define points of interest for the centers of Antakya and Altınözü.
  // A buffer is used to average over a representative urban area.
  const antakyaPoint = ee.Geometry.Point([36.1600, 36.2025]);
  const altinozuPoint = ee.Geometry.Point([36.3533, 36.1139]);

  const antakyaGeom = antakyaPoint.buffer(2000); // 2km buffer
  const altinozuGeom = altinozuPoint.buffer(2000); // 2km buffer

  // Define the start and end periods for comparison.
  const startDate = '2023-02-01';
  const endDate = '2023-02-28';
  const postDate = '2023-04-01';
  const postEndDate = '2023-04-30';

  // 2. Data Acquisition & Check
  const collectionId = 'NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG';
  const band = 'avg_rad';

  // Get the images for the specified months.
  const imageStart = ee.ImageCollection(collectionId)
    .filterDate(startDate, endDate)
    .select(band)
    .mean();

  const imageEnd = ee.ImageCollection(collectionId)
    .filterDate(postDate, postEndDate)
    .select(band)
    .mean();

  // 3. Processing & Calculation
  const scale = 500; // Native resolution is ~500m

  // Define a reducer to get both mean radiance and pixel count.
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  // Calculate statistics for Antakya.
  const antakyaStatsStart = imageStart.reduceRegion({
    reducer: reducer,
    geometry: antakyaGeom,
    scale: scale,
    maxPixels: 1e9
  });
  const antakyaStatsEnd = imageEnd.reduceRegion({
    reducer: reducer,
    geometry: antakyaGeom,
    scale: scale,
    maxPixels: 1e9
  });

  // Calculate statistics for Altınözü.
  const altinozuStatsStart = imageStart.reduceRegion({
    reducer: reducer,
    geometry: altinozuGeom,
    scale: scale,
    maxPixels: 1e9
  });
  const altinozuStatsEnd = imageEnd.reduceRegion({
    reducer: reducer,
    geometry: altinozuGeom,
    scale: scale,
    maxPixels: 1e9
  });

  // Retrieve the results from the server.
  const [
    antStart, antEnd, altStart, altEnd
  ] = await ee.Promise.all([
    ee.Dictionary(antakyaStatsStart).evaluate(),
    ee.Dictionary(antakyaStatsEnd).evaluate(),
    ee.Dictionary(altinozuStatsStart).evaluate(),
    ee.Dictionary(altinozuStatsEnd).evaluate()
  ]).catch((error) => {
    console.log(`Error during GEE evaluation: ${error.message}`);
    return [null, null, null, null];
  });

  // 4. Validation & Final Answer
  if (!antStart || !antEnd || !altStart || !altEnd) {
      console.log('Calculation failed during server request.');
      console.log('A'); // C3
      return;
  }

  // Check for valid pixels.
  if (!antStart.avg_rad_count || !antEnd.avg_rad_count || !altStart.avg_rad_count || !altEnd.avg_rad_count) {
      console.log('No valid pixels found in one or more regions.');
      console.log('C2');
      return;
  }

  // Check if radiance values are null or undefined.
  if (antStart.avg_rad == null || antEnd.avg_rad == null || altStart.avg_rad == null || altEnd.avg_rad == null) {
      console.log('Calculation resulted in null radiance values.');
      console.log('C3');
      return;
  }

  // Calculate the increase for each city.
  const antakyaIncrease = antEnd.avg_rad - antStart.avg_rad;
  const altinozuIncrease = altEnd.avg_rad - altStart.avg_rad;

  console.log(`Antakya Radiance (Feb 2023): ${antStart.avg_rad.toFixed(2)}`);
  console.log(`Antakya Radiance (Apr 2023): ${antEnd.avg_rad.toFixed(2)}`);
  console.log(`Antakya Increase: ${antakyaIncrease.toFixed(2)}`);
  console.log(`Altinozu Radiance (Feb 2023): ${altStart.avg_rad.toFixed(2)}`);
  console.log(`Altinozu Radiance (Apr 2023): ${altEnd.avg_rad.toFixed(2)}`);
  console.log(`Altinozu Increase: ${altinozuIncrease.toFixed(2)}`);

  if (antakyaIncrease > altinozuIncrease) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or Analysis failed: ${e}`);
    console.log('D');
  }
}

initEE();
